-- ============================================================
-- Datos de prueba: 100 empresas, 100 estudiantes, 100 prácticas
-- Ejecutar DESPUÉS de instalacion_completa.sql
-- Cada empresa y cada estudiante tiene su usuario asignado.
-- Clave de TODOS los usuarios nuevos: la misma que los usuarios demo.
-- Usuarios: empresa001..empresa100 / estudiante001..estudiante100
-- ============================================================
USE sistema_practicas;
SET NAMES utf8mb4;

SET @r_empresa=(SELECT id_rol FROM roles WHERE codigo='empresa');
SET @r_estudiante=(SELECT id_rol FROM roles WHERE codigo='estudiante');
SET @u_activo=(SELECT id_estado FROM estados WHERE tipo_entidad='usuario' AND codigo='activo');
SET @emp_pendiente=(SELECT id_estado FROM estados WHERE tipo_entidad='empresa' AND codigo='pendiente');
SET @emp_aprobada=(SELECT id_estado FROM estados WHERE tipo_entidad='empresa' AND codigo='aprobada');
SET @emp_rechazada=(SELECT id_estado FROM estados WHERE tipo_entidad='empresa' AND codigo='rechazada');
SET @pr_borrador=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='borrador');
SET @pr_pendiente_revision=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='pendiente_revision');
SET @pr_cambios_solicitados=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='cambios_solicitados');
SET @pr_rechazada=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='rechazada');
SET @pr_publicada=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='publicada');
SET @pr_cerrada=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='cerrada');
SET @pr_cancelada=(SELECT id_estado FROM estados WHERE tipo_entidad='practica' AND codigo='cancelada');

-- Usuarios de empresas

-- Usuarios de estudiantes

SELECT 'usuario',id_usuario,NULL,id_estado,id_usuario,'Cuenta de prueba.',id_usuario FROM usuarios WHERE id_usuario BETWEEN 1001 AND 1100 OR id_usuario BETWEEN 2001 AND 2100;

-- Empresas (90 aprobadas, 5 pendientes, 5 rechazadas)

SELECT 'empresa',id_empresa,NULL,id_estado_revision,id_usuario,'Estado inicial de prueba.',id_usuario FROM empresas WHERE id_empresa BETWEEN 1001 AND 1100;

-- Estudiantes

-- Prácticas (1 por empresa; las de empresas no aprobadas quedan en borrador)

SELECT 'practica',id_practica,NULL,id_estado,creado_por,'Estado inicial de prueba.',creado_por FROM practicas WHERE id_practica BETWEEN 1001 AND 1100;

-- Verificación rápida
SELECT (SELECT COUNT(*) FROM empresas) empresas,(SELECT COUNT(*) FROM estudiantes) estudiantes,(SELECT COUNT(*) FROM practicas) practicas,(SELECT COUNT(*) FROM usuarios) usuarios;
